import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int t = Integer.parseInt(st.nextToken()); PrintWriter out = new PrintWriter(System.out); while (t-- > 0) { st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int m = Integer.parseInt(st.nextToken()); st = new StringTokenizer(br.readLine()); int count = 0; for (int i = 0; i < n; i++) { int a = Integer.parseInt(st.nextToken()); if (a % m == 0) { count++; } } long result = (1L << count) - 1; out.println(result); } out.flush(); out.close(); } }